#include <string.h>
#include <stdbool.h>

static bool is_permutation(const char *a, const char *b) {
    size_t len_a = strlen(a);
    if (len_a != strlen(b)) {
        return false;
    }
    char b_array[len_a + 1];
    strcpy(b_array, b);
    int found = 0;
    for (size_t i = 0; i < len_a; i++) {
        for (size_t k = 0; k < len_a; k++) {
            if (a[i] == b_array[k]) {
                found++;
                b_array[k] = (char) 0xFF;
                break;
            }
        }
    }
    return found == (int) len_a;
}

