static int solution(int x, const int *a, int length) {
    char *seen = calloc(x + 1, sizeof(char));
    int distinct = 0;
    for (int i = 0; i < length; i++) {
        if (a[i] <= x && !seen[a[i]]) {
            seen[a[i]] = 1;
            distinct++;
        }
        if (distinct == x) {
            free(seen);
            return i;
        }
    }
    free(seen);
    return -1;
}

