def zero_front(nums):
    if nums is None:
        return None
    result = [0] * len(nums)
    zeros_pos = 0
    for value in nums:
        if value == 0:
            result[zeros_pos] = 0
            zeros_pos += 1
    fill = len(nums) - 1
    for value in reversed(nums):
        if value != 0:
            result[fill] = value
            fill -= 1
    return result

