#include <stdlib.h>

int *zero_front(const int *nums, int length) {
    if (nums == NULL) {
        return NULL;
    }
    int *result = calloc(length, sizeof(int));
    int zeros_pos = 0;
    for (int i = 0; i < length; i++) {
        if (nums[i] == 0) {
            result[zeros_pos] = 0;
            zeros_pos++;
        }
    }
    int others_pos = length - 1;
    for (int i = length - 1; i >= 0; i--) {
        if (nums[i] != 0) {
            result[others_pos] = nums[i];
            others_pos--;
        }
    }
    return result;
}

